"""Regenerate docs/RULES.md from the rule definitions.

Run after adding or changing a rule:  python tools/gen_rules_doc.py
A test fails if the doc is out of date, so the docs can't drift from the code.
"""

from pathlib import Path

from atlas_scan.models import CATEGORIES
from atlas_scan.scanners import all_rules

OUT = Path(__file__).resolve().parent.parent / "docs" / "RULES.md"


def render() -> str:
    lines = [
        "# Rules",
        "",
        "Every check the scanner runs. Generated by `tools/gen_rules_doc.py`; don't edit by hand.",
        "",
        "Silence a finding on one line with `# atlas: ignore[RULE_ID]` (or `// atlas: ignore[RULE_ID]`).",
        "",
    ]
    rules = all_rules()
    for cat, label in CATEGORIES.items():
        group = [r for r in rules if r.category == cat]
        lines += [f"## {label}", "", "| ID | Severity | Rule |", "|---|---|---|"]
        lines += [f"| [{r.id}](#{r.id.lower()}) | {r.severity} | {r.title} |" for r in group]
        lines.append("")
        for r in group:
            lines += [f"### {r.id}", "", f"**{r.title}** · severity: {r.severity}" +
                      (f" · {r.cwe}" if r.cwe else ""), ""]
            if r.fix:
                lines += [f"**Fix:** {r.fix}", ""]
    return "\n".join(lines).rstrip() + "\n"


if __name__ == "__main__":
    OUT.write_text(render(), encoding="utf-8")
    print(f"wrote {OUT}")
